   362  /* return "data" from {abstract data} string */
   363  char *theme_format_expand_get(THEME_REC *theme, const char **format)
   364  {
   365          GString *str;
   366          char *ret;
   367          theme_rm_col dummy, reset;
   368          int braces = 1; /* we start with one brace opened */
   369          dummy.m[0] = '\0';
   370          strcpy(reset.m, "n");
   371
   372          str = g_string_new(NULL);
   373          while (**format != '\0' && braces != 0) {
   374                  if (**format == '{')
   375                          braces++;
   376                  else if (**format == '}')
   377                          braces--;
   378                  else if ((braces > 1) && (**format == ' ')) {
   379                          g_string_append(str, "\\x20");
   380                          (*format)++;
   381                          continue;
   382                  } else {
   383                          theme_format_append_next(theme, str, format,
   384                                                   reset, reset,
   385                                                   &dummy, &dummy, 0);
   386                          continue;
   387                  }
   388
   389                  if (braces == 0) {
   390                          (*format)++;
   391                          break;
   392                  }
   393
   394                  g_string_append_c(str, **format);
   395                  (*format)++;
   396          }
   397
   398          ret = str->str;
   399          g_string_free(str, FALSE);
   400          return ret;
   401  }
