   408  /* expand a single {abstract ...data... } */
   409  static char *theme_format_expand_abstract(THEME_REC *theme, const char **formatp,
   410                                            theme_rm_col *last_fg, theme_rm_col *last_bg, int flags,
   411                                            GTree *block_list)
   412  {
   413          GString *str;
   414          const char *p, *format;
   415          char *abstract, *data, *ret;
   416          theme_rm_col default_fg, default_bg;
   417          int len;
   418
   419          format = *formatp;
   420          default_fg = *last_fg;
   421          default_bg = *last_bg;
   422
   423          /* get abstract name first */
   424          p = format;
   425          while (*p != '\0' && *p != ' ' &&
   426                 *p != '{' && *p != '}') p++;
   427          if (*p == '\0' || p == format)
   428                  return NULL; /* error */
   429
   430          len = (int) (p-format);
   431          abstract = g_strndup(format, len);
   432
   433          /* skip the following space, if there's any more spaces they're
   434             treated as arguments */
   435          if (*p == ' ') {
   436                  len++;
   437                  if ((flags & EXPAND_FLAG_IGNORE_EMPTY) && data_is_empty(&p)) {
   438                          *formatp = p;
   439                          g_free(abstract);
   440                          return NULL;
   441                  }
   442          }
   443          *formatp = format+len;
   444
   445          if (block_list == NULL) {
   446                  block_list = g_tree_new_full((GCompareDataFunc) g_strcmp0, NULL, g_free, NULL);
   447          } else {
   448                  g_tree_ref(block_list);
   449          }
   450
   451          /* get the abstract data */
   452          data = g_hash_table_lookup(theme->abstracts, abstract);
   453          if (data == NULL || g_tree_lookup(block_list, abstract) != NULL) {
   454                  /* unknown abstract, just display the data */
   455                  data = "$0-";
   456                  g_free(abstract);
   457          } else {
   458                  g_tree_insert(block_list, abstract, abstract);
   459          }
   460          abstract = g_strdup(data);
   461
   462          /* we'll need to get the data part. it may contain
   463             more abstracts, they are _NOT_ expanded. */
   464          data = theme_format_expand_get(theme, formatp);
   465          len = strlen(data);
   466
   467          if (len > 1 && i_isdigit(data[len-1]) && data[len-2] == '$') {
   468                  /* ends with $<digit> .. this breaks things if next
   469                     character is digit or '-' */
   470                  char digit, *tmp;
   471
   472                  tmp = data;
   473                  digit = tmp[len-1];
   474                  tmp[len-1] = '\0';
   475
   476                  data = g_strdup_printf("%s{%c}", tmp, digit);
   477                  g_free(tmp);
   478          }
   479
   480          ret = parse_special_string(abstract, NULL, NULL, data, NULL,
   481                                     PARSE_FLAG_ONLY_ARGS);
   482          g_free(abstract);
   483          g_free(data);
   484          str = g_string_new(NULL);
   485          p = ret;
   486          while (*p != '\0') {
   487                  if (*p == '\\') {
   488                          int chr;
   489                          p++;
   490                          chr = expand_escape(&p);
   491                          g_string_append_c(str, chr != -1 ? chr : *p);
   492                  } else
   493                          g_string_append_c(str, *p);
   494                  p++;
   495          }
   496          g_free(ret);
   497          abstract = str->str;
   498          g_string_free(str, FALSE);
   499
   500          /* abstract may itself contain abstracts or replaces */
   501          p = abstract;
   502          ret = theme_format_expand_data_rec(theme, &p, default_fg, default_bg, last_fg, last_bg,
   503                                             flags | EXPAND_FLAG_LASTCOLOR_ARG, block_list);
   504          g_free(abstract);
   505          g_tree_unref(block_list);
   506          return ret;
   507  }
