   509  static char *theme_format_expand_data_rec(THEME_REC *theme, const char **format,
   510                                            theme_rm_col default_fg, theme_rm_col default_bg,
   511                                            theme_rm_col *save_last_fg, theme_rm_col *save_last_bg,
   512                                            int flags, GTree *block_list)
   513  {
   514          GString *str;
   515          char *ret, *abstract;
   516          theme_rm_col last_fg, last_bg;
   517          int recurse_flags;
   518
   519          last_fg = default_fg;
   520          last_bg = default_bg;
   521          recurse_flags = flags & EXPAND_FLAG_RECURSIVE_MASK;
   522
   523          str = g_string_new(NULL);
   524          while (**format != '\0') {
   525                  if ((flags & EXPAND_FLAG_ROOT) == 0 && **format == '}') {
   560                  if (abstract != NULL) {
   561                          g_string_append(str, abstract);
   562                          g_free(abstract);
   563                  }
   564          }
   565
   566                  /* save the last color */
   567                  if (save_last_fg != NULL)
   568                          *save_last_fg = last_fg;
   569                  if (save_last_bg != NULL)
   570                          *save_last_bg = last_bg;
   571
   572          ret = str->str;
   573          g_string_free(str, FALSE);
   574          return ret;
   575  }
